create table jira_draft(id uuid primary key,case_id uuid not null unique,title text not null,problem_statement text not null,evidence_summary text not null,proposed_direction text not null,acceptance_intent text not null,repository_id text not null,review_date date not null,approved boolean not null,updated_at timestamptz not null);
create table disposition_attempt(id uuid primary key,case_id uuid not null,correlation_key text not null unique,jira_key text not null,jira_url text not null,created_at timestamptz not null);
create table improvement_follow_up(id uuid primary key,case_id uuid not null,jira_key text not null unique,jira_url text not null,review_date date not null,state text not null check(state in ('OPEN','CLOSED')),final_rationale text,created_at timestamptz not null);
